actions.script:
const escape = (line) => line.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
const text = String(bodyText || '').replace(/\r\n?/g, '\n').trim()
if (!text) ec.message.addError(ec.l10n.localize('Write a message first'))
else if (ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', chatRoomId || '').condition('encrypted', 'Y').count())
    ec.message.addError(ec.l10n.localize('This room is end-to-end encrypted: open it in a browser to write in it'))
else ec.service.sync().name('org.moqui.comms.ChatScreenServices.send#ChatMessage').parameters({chatRoomId: chatRoomId || '',
    body: text.split(/\n{2,}/).map((part) => '<p>' + part.split('\n').map(escape).join('<br>') + '</p>').join('')}).call()

for (const id of String(deliveryIds || '').split(',').map((part) => part.trim()).filter((part) => part)) {
    ec.service.sync().name('org.moqui.impl.ChatBridgeServices.retry#Delivery').parameter('chatBridgeDeliveryId', id).call()
    if (ec.message.hasError()) break
}
if (!ec.message.hasError()) ec.message.addMessage(ec.l10n.localize('Sending again'), 'success')

const when = (millis) => millis ? ec.l10n.format(new Date(Number(millis)), 'MMM d, h:mm a') : ''
roomList = []
eventList = []
room = null
canPost = false
canJoin = false
encryptedRoom = false
unreadTotal = 0
bridgeText = ''
notConnected = false
if (chatRoomId) {
    const out = ec.service.sync().name('org.moqui.comms.ChatScreenServices.get#RoomView').parameters({chatRoomId: chatRoomId, limit: 30}).call()
    if (!ec.message.hasError() && out.room) {
        room = out.room
        encryptedRoom = !!room.encrypted
        canPost = !!(out.access && out.access.canPost) && !encryptedRoom
        canJoin = !!(out.access && out.access.canJoin)
        const canModerate = !!(out.access && out.access.canModerate)
        const networks = Array.from(new Set(Array.from(room.bridges || []).map((bridge) => bridge.networkName || bridge.name).filter((name) => name)))
        bridgeText = networks.length ? ec.resource.expand(ec.l10n.localize('Messages here also go to ${names}'), '', {names: networks.join(', ')}) : ''
        notConnected = !!room.notConnected
        const STATES = {accepted: 'Delivered', pending: 'Sending', failed: 'Not delivered', uncertain: 'May not have arrived'}
        const page = out.timeline || {}
        const names = page.userNames || {}
        eventList = Array.from(page.eventList || []).map((event) => {
            const files = event.encrypted ? [] : Array.from(event.attachments || []).map((file) => file.fileName || file.name || '').filter((name) => name)
            let text = event.redacted ? (event.removedLabel || ec.l10n.localize('Message removed'))
                : event.encrypted ? ec.l10n.localize('Encrypted message')
                : (event.bodyText || (event.poll ? ec.l10n.localize('Poll') + ': ' + (event.poll.question || '') : ''))
            if (files.length) text = (text ? text + ' ' : '') + '[' + files.join(', ') + ']'
            if (!text && event.type !== 'message') {
                const content = event.content || {}
                const who = names[content.userId] || content.userId || ''
                text = '(' + (event.type || event.eventTypeEnumId || '') + (who ? ': ' + who : '') + ')'
            }
            if (event.edited) text += ' ' + ec.l10n.localize('(edited)')
            if (Number(event.threadReplyCount || 0) > 0) text += ' · ' + event.threadReplyCount + ' ' + ec.l10n.localize(event.threadReplyCount == 1 ? 'reply' : 'replies')
            const delivery = event.delivery || null
            const failed = delivery ? Array.from(delivery.destinations || []).find((destination) => destination.error && destination.state !== 'accepted') : null
            const retryIds = delivery && delivery.retryable && (event.senderUserId === ec.user.userId || canModerate)
                    ? Array.from(delivery.destinations || []).filter((destination) => destination.retryable).map((destination) => destination.chatBridgeDeliveryId).join(',') : ''
            return {eventSeq: event.eventSeq, senderName: (event.senderName || names[event.senderUserId] || '')
                    + (event.senderExternal ? ' (' + (event.senderExternal.networkName || ec.l10n.localize('Outside')) + ')' : ''),
                timeText: when(event.sentDate), text: text,
                deliveryText: delivery ? ec.l10n.localize(STATES[delivery.state] || delivery.state) + (failed ? ': ' + failed.error : '') : '',
                retryIds: retryIds}
        })
    }
} else {
    const out = ec.service.sync().name('org.moqui.comms.ChatScreenServices.get#ChatData').parameter('limit', limit ? Number(limit) : 200).call()
    if (!ec.message.hasError()) {
        unreadTotal = out.unreadTotal || 0
        roomList = Array.from(out.roomList || []).map((item) => {
            const last = item.lastMessage || null
            const counts = [Number(item.unreadCount || 0) > 0 ? item.unreadCount + ' ' + ec.l10n.localize('unread') : '',
                Number(item.mentionCount || 0) > 0 ? '@' + item.mentionCount : ''].filter((part) => part).join(' ')
            const bridged = item.bridged ? ' [' + (Array.from(item.bridgeNetworkNames || []).join(', ') || ec.l10n.localize('bridged'))
                    + (item.notConnected ? ', ' + ec.l10n.localize('not connected') : '') + ']' : ''
            return {chatRoomId: item.chatRoomId, nameText: (item.isPinned ? '* ' : '') + (item.displayName || item.roomName || item.chatRoomId) + bridged
                    + (item.isMuted ? ' ' + ec.l10n.localize('(muted)') : ''),
                countText: counts, lastText: last ? (last.senderName ? last.senderName + ': ' : '') + (last.encrypted ? ec.l10n.localize('Encrypted message') : last.snippet || '') : '',
                timeText: last ? when(last.sentDate) : ''}
        })
    }
}
roomTitle = room ? (room.displayName || room.roomName || chatRoomId) : ''
roomTopic = room && room.topic ? room.topic : ''
chatDraft = {chatRoomId: chatRoomId || '', bodyText: ''}
